import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSultanpurData(){const e=readFileSync(resolve(__dirname,"../../frontend/sultanpur-national-park-explorer/sultanpur-data.js"),"utf-8");return new Function(e+"\nreturn { SULTANPUR_INFO, ECOLOGY_HYDROLOGY, BIRD_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Sultanpur National Park & Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadSultanpurData()}),describe("SULTANPUR_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.SULTANPUR_INFO.id).toBe("sultanpur-national-park"),expect(e.SULTANPUR_INFO.name).toContain("Sultanpur"),expect(e.SULTANPUR_INFO.ramsarYear).toBe(2021),expect(e.SULTANPUR_INFO.ramsarSiteNo).toBe(2459),expect(e.SULTANPUR_INFO.state).toBe("Haryana")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SULTANPUR_INFO.quickStats)).toBe(!0),expect(e.SULTANPUR_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, hydrology, history, and status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.hydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.history).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of waterfowl species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Bar-headed Goose and Black-necked Stork",()=>{const t=e.BIRD_SPECIES.find(e=>"bar-headed-goose"===e.id),a=e.BIRD_SPECIES.find(e=>"black-necked-stork"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"sultanpur-national-park"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../sultanpur-national-park-explorer/index.html")})})});